(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sv"] = {"ui":{"skip":"Hoppa till innehållet","back":"← Tillbaka till AI-gile","lang.button":"Språk: {name}","lang.dialog":"Välj språk","lang.search":"Sök språk","lang.none":"Inget språk matchar","lang.notYet":"{name} är inte översatt än","theme.aria":"Växla mellan ljust och mörkt tema","theme.toLight":"Byt till ljust tema","theme.toDark":"Byt till mörkt tema","index.title":"AI-gile: ditt AI-utvecklarteam på en tavla","index.description":"AI-gile är en kanbantavla för AI-kodteam. De jobbar medan du sover; du får en kort hög med saker att avgöra, testa och godkänna.","hero.logoAlt":"AI-gile-tavlans ikon","hero.h1.html":"Ditt AI-utvecklarteam på en&nbsp;tavla.","hero.alpha":"🐣 Stängd pre-alfa","hero.alphaTitle":"Tidigt och ofärdigt: tack för att du testar!","hero.lede":"De bygger medan du sover. Du vaknar till en kort hög: några frågor, några saker att testa, en eller två lila diamanter. Klicka, godkänn, tillbaka till kaffet.","dl.windows":"Windows-app","dl.browser":"Kör den i webbläsaren","dl.soon":"Kommer snart","dl.notify":"🔔 Säg till när den öppnar","dl.notifySmall":"Alfa eller beta","hero.secondary":"Agilt, men teamet behöver aldrig stå-upp-kaffe. (De har stå-upp-möten ändå.)","pitch.h2":"AI-gile med precis så många ord du vill","pitch.lede":"Välj en längd, från ett ord till 144. Varje längd är en egen beskrivning, skriven för just den storleken. Dra i reglaget eller använd piltangenterna.","pitch.rangeLabel":"Längd i ord","pitch.dice":"🎲 en annan version","pitch.words.one":"{n} ord","pitch.words.other":"{n} ord","pitch.letters.one":"{n} bokstav","pitch.letters.other":"{n} bokstäver","pitch.chars.one":"{n} tecken","pitch.chars.other":"{n} tecken","count.line.html.one":"{n} kort på tavlan just nu","count.line.html.other":"{n} kort på tavlan just nu","features.aria":"Vad den gör","f.pile.h":"En hög åt dig","f.pile.html":"<b>Till dig</b> samlar allt som väntar på dig, över alla projekt: frågor, saker att testa, uppgifter som bara en människa kan göra. Din kö visar vad som är näst och hur lång tid det tar.","f.sleep.h":"Team som jobbar medan du sover","f.sleep.p":"Varje projekt har en lead och ett team av AI-agenter. Kommentera ett kort så vaknar teamet, gör jobbet och lämnar tillbaka det med steg som en trött människa kan följa.","f.tester.h":"En AI-testare kollar först","f.tester.p":"Innan något når dig följer en testare stegen i en kopia av appen och visar vad den såg, med en skärmbild. Bläddra igenom de godkända och godkänn med ett klick.","f.proof.h":"Bevis, inte löften","f.proof.p":"Varje överlämning visar vad som ändrats: filerna, diffen, skärmbilderna. Du slipper öppna varje app för att se om det är klart.","f.chat.h":"Chatta med dina leads","f.chat.p":"Ett fält som i Discord: en ikon per projekt, lila diamanter för det som behöver dig. Skriv en idé till en lead; den gör kort och en plan av den, med en ✅ Kör-knapp.","f.tidy.h":"Städar efter sig själv","f.tidy.p":"Besläktade kort slås ihop, rörigt formulerade titlar rättas till och en tokenkoll håller koden slimmad. Färre saker att växla mellan, mindre att tänka på.","f.private.h":"Din, på din dator","f.private.li1":"Tavlan körs på din egen dator och svarar bara dig.","f.private.li2":"Privata meddelanden mellan människor är end-to-end-krypterade.","f.private.li3":"Inga konton, inga spårare, inga kakor.","f.lang.h":"På ditt språk","f.lang.p":"Över 120 språk, från holländska, walesiska och japanska till pirat, Yoda och klingonska, med ett snabbt byte tillbaka till engelska för utvecklarorden.","tl.aria":"Tidslinje från första samtalet till planen framåt","tl.h2":"Från första chatten till det som kommer","tl.lede":"Riktiga datum och klockslag, i din egen tidszon. Efter idag är det planen, utan utlovade datum.","tl.today":"Idag","tl.planned":"planerat","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Häng med","join.lede":"AI-gile byggs av en liten människa och ett stort antal tålmodiga agenter. Just nu är det privat, en sluten alfa med vänner. Vill du prova när den öppnar?","join.btn":"Anmäl intresse","join.small":"Vi mejlar dig, inget annat","footer.tag":"AI-gile. Inga spårare, inga kakor, inget stå-upp-kaffe.","footer.licence":"Företagslicens","footer.status":"Status","form.sending":"Skickar…","form.failed":"Det gick inte: försök igen senare.","form.offline":"Kunde inte nå AI-gile: försök igen senare.","interest.title":"AI-gile: säg till när alfan öppnar","interest.description":"Lämna din e-post så hör du när AI-giles slutna alfa eller beta öppnar.","interest.h1":"🔔 Säg till när den öppnar","interest.lede":"AI-gile är i sluten pre-alfa. Lämna din e-post så skriver vi en gång, när det finns en plats åt dig.","interest.email":"Din e-post","interest.which":"Vilket test?","interest.alpha":"Sluten alfa: tidigt, ojämnt, många ändringar","interest.beta":"Beta: stadigare, senare","interest.both":"Vilket som, det som kommer först","interest.submit":"Sätt upp mig på listan","interest.thanks":"Tack! Du står på listan.","licence.title":"AI-gile: företagslicens","licence.description":"Använder du AI-gile i ditt företag? Ansök om en gratis företagslicens.","licence.h1":"📜 Företagslicens","licence.lede":"Använder du AI-gile på jobbet? Berätta vem du är och vad ni gör. Om det gör något gott är licensen gratis.","licence.company":"Företag","licence.website":"Webbplats","licence.what":"Vad ni gör","licence.how":"Hur det hjälper världen","licence.email":"E-post","licence.submit":"Ansök","licence.thanks":"Tack! Vi svarar via e-post.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Lugnt just nu","status.checking":"Kollar…","status.offline":"Kommer inte åt statustjänsten just nu (försöker igen)","status.updated":"uppdaterad {ago}","status.justNow":"nyss","status.min":"för {n} min sedan","status.hours":"för {n} tim sedan","status.days":"för {n} d sedan","live.h2":"Se det byggas, live","live.caption":"Varje kort är dolt: du ser arbetets form, inte orden.","live.watching.one":"live: {n} tittar","live.watching.other":"live: {n} tittar","live.offline":"Live-tavlan tar en liten paus. Titta in igen snart.","live.cols":"Backlog|To do|Pågår|Teamet kollar|Till dig att testa|Till teamet|Klart","live.last.now":"Senaste kortet flyttades nyss","live.last.min.one":"Senaste kortet flyttades för {n} min sedan","live.last.min.other":"Senaste kortet flyttades för {n} min sedan","live.last.hour.one":"Senaste kortet flyttades för {n} timme sedan","live.last.hour.other":"Senaste kortet flyttades för {n} timmar sedan","live.last.day.one":"Senaste kortet flyttades för {n} dag sedan","live.last.day.other":"Senaste kortet flyttades för {n} dagar sedan"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotar.","Delegerat."]},{"n":2,"texts":["Kanban, automatiserat.","Agenter, organiserade.","Idéer, byggda."]},{"n":3,"texts":["Kanban för robotar.","Idéer blir funktioner.","Gratis agentkanban, tack."]},{"n":5,"texts":["Kanbantavla som agenter sköter åt dig.","Du skriver kort. Agenter bygger.","Gratis, lokalt, testat, lite fånigt."]},{"n":8,"texts":["En gratis kanbantavla där AI-agenter gör jobbet åt dig.","Skriv en idé. Agenterna bygger den. Du godkänner.","Agilt för en människa och många tålmodiga robotar."]},{"n":13,"texts":["En kanbantavla på din egen dator där AI-agenter plockar upp korten och bygger.","Skriv en idé. Ett team av agenter bygger den. En testare kollar den.","Gratis, utan konton och spårare: en tavla, några robotar och du som bestämmer."]},{"n":21,"texts":["AI-gile är en kanbantavla för dig som jobbar med AI-kodagenter. De plockar upp korten; du testar och godkänner dem.","Varje projekt får en lead och ett team av AI-agenter. Kommentera vilket kort som helst så sätter sig teamet och jobbar.","En gratis, personlig att göra-tavla som körs på din egen dator. Arbetarna är robotar. Den som säger ja är du."]},{"n":34,"texts":["Du lägger idéer på en tavla. Ett team av AI-agenter förvandlar dem till fungerande funktioner, testar dem och lämnar tillbaka dem med steg att prova. Ingenting räknas som klart förrän du säger det.","AI-gile är en hemmabyggd kanbantavla som Rich byggt med mycket hjälp av de agenter som den nu styr. Den är gratis, körs på din dator och delas med vänner, den säljs inte.","Tänk dig en vanlig kanbantavla, med kolumner från Backlog till Klart, förutom att korten plockas upp av AI-agenter. De rapporterar framsteg, frågar när de kört fast och väntar alltid på din tumme upp."]},{"n":55,"texts":["AI-gile är en kanbantavla där teamet består av AI-agenter. Varje projekt har en lead som planerar arbetet och hjälpare som bygger. När en funktion är klar provar en AI-testare den och tar en skärmbild, och sedan hamnar den i din hög. Godkänn den, eller kommentera så gör de om den.","Det började som en enda persons sätt att hålla reda på många AI-kodsessioner samtidigt, och växte till en riktig tavla. Den körs på din dator, kräver inget konto och har inga spårare. Den är gratis för vänner och nyfikna. Den är också ofärdig, så räkna med ojämnheter och en och annan överraskning.","Här kommer den ärliga versionen. Du måste fortfarande ha idéerna, och du måste fortfarande kontrollera resultaten. Det AI-gile gör är allt däremellan: det håller korten i ordning, väcker rätt agent när du kommenterar, visar exakt vad som ändrats och samlar allt i en enda kort hög åt dig."]},{"n":89,"texts":["AI-gile är en gratis kanbantavla som du kör på din egen dator. I stället för människor har varje projekt ett team av AI-agenter: en lead som gör dina idéer till kort och en plan, och hjälpare som tar korten i prioritetsordning. När något är byggt följer en AI-testare teststegen och visar dig vad den såg. Sedan väntar det i en enda hög som heter Till dig. Du godkänner det, eller så kommenterar du och teamet försöker igen. Ingenting når någonsin Klart utan dig.","Några saker du kanske inte väntar dig. En nattvakt fyller på To do medan du sover och väljer kort som inte behöver något svar från dig. En tokenräknare visar hur mycket agenterna har använt i dag och den här veckan, och No Token Mode säger åt dem att sluta spendera. Du kan skriva till vänner, och privata meddelanden är end-to-end-krypterade. Tavlan talar ungefär 120 språk, bland annat holländska, flamländska, pirat och klingonska. Inget av det kostar en krona, och ingen försöker sälja något till dig heller.","AI-gile är ett litet, personligt projekt, inte ett företag. Rich ville ta hand om flera AI-kodprojekt utan att öppna varje app för att kolla läget, så han och agenterna byggde en tavla för det, och använde sedan tavlan för att bygga resten av sig själv. Den är i sluten pre-alfa, vilket betyder att den fungerar, mestadels, för en handfull vänner. Här finns ingen prissida, inget nyhetsbrev och ingen tillväxtplan. Låter det användbart kan du be om att få prova när den öppnar sig lite mer."]},{"n":144,"texts":["AI-gile är en kanbantavla för en människa och många AI-agenter. Den körs på din egen dator och är helt gratis. Du lägger till projekt, och varje projekt får en lead och ett litet team. Du chattar med leaden, ungefär som i Discord, och beskriver en idé; leaden gör kort och en plan av den och väntar sedan på att du trycker på Kör. Teamet arbetar sig igenom korten i prioritetsordning, med ett enkelt kommandoradsverktyg gjort för språkmodeller. Innan något kommer tillbaka till dig följer en AI-testare stegen i en kopia av appen och bifogar en skärmbild. Färdigt arbete hamnar i din hög med de ändrade filerna och diffen. Du godkänner det, eller så lämnar du en kommentar och teamet vaknar och försöker igen. Bara du kan flytta ett kort till Klart.","En dag med AI-gile, ungefär. På kvällen lämnar du några kommentarer: den här knappen sitter fel, den där listan borde sorteras, kunde vi få ett mörkt läge. Du går och lägger dig. Agenterna läser kommentarerna, gör ändringarna, testar dem och lämnar tillbaka dem till dig. Om To do tar slut fyller nattvakten på från backloggen med kort som inte kräver något svar från dig. På morgonen ligger det en enda kort hög: ett par frågor och några saker att prova, var och en med steg som en sömnig människa kan följa och en skärmbild på hur det fungerar. Du klickar dig igenom, godkänner de bra och skickar tillbaka resten. En tokenräknare visar vad allt kostade i användning, och No Token Mode finns för snåla veckor. Sedan äter du frukost, och där kan agenterna inte hjälpa till än.","Först, vad AI-gile inte är. Det är inte en startup, det är inte till salu och ingen samlar in dina data. Det är en gratis tavla som körs på din dator, utan konton, utan spårare och utan kakor. Vad det är: ett städat ställe att se alla dina AI-kodprojekt på en gång, med ett team av agenter som tar korten och du som fattar besluten. Den slår ihop besläktade kort, rättar rörigt formulerade titlar och håller koll på hur slimmad koden förblir. Den talar ungefär 120 språk, från holländska och flamländska till pirat och klingonska. Vänner kan skriva till varandra, privat och krypterat. Den byggdes av Rich och ett stort antal tålmodiga agenter, mest genom att använda sig själv. Den är i sluten pre-alfa, så den är ojämn på sina ställen. Låter det kul? Fråga snällt så kanske du kommer in tidigt."]}],"quips":{"1":"Ett ord. Djärvt. Kanske för djärvt.","3":"Tre ord. Redan ärligare än de flesta produktsidor.","8":"Åtta ord. Fortfarande kortare än ett stå-upp-möte.","21":"Längderna är förresten story points. Såklart att de är.","55":"Femtiofem ord. Två kort blev klara medan du läste det.","144":"Det var den långa. Det finns ingen 233. Agenterna har gått och lagt sig."}},"timeline":{"first-idea.name":"Den första idén","first-idea.line":"Det allra första samtalet, innan någon kod fanns.","first-board.name":"Första tavlan","first-board.line":"En tavla som håller reda på sitt eget bygge: kort, kolumner, dra och släpp, projekt.","team-roles.name":"Team och roller","team-roles.line":"Agentprofiler, teammallar, utrymmen och vem som gör vad.","install.name":"Installation och versioner","install.line":"En zip som en vän kan installera, självuppdatering, kanaler och återställning.","usage-saver.name":"Användningssparare","usage-saver.line":"Mät vad körningar kostar, håll koden slimmad, spara din gräns.","friends.name":"Vänner och delning","friends.line":"Privata meddelanden, ett förvrängt relä, inbjudningar, roller och delade projekt.","languages.name":"Språk","languages.line":"Varje skärmtext i en språkfil, med holländska och flamländska först.","ai-tester.name":"AI-testare","ai-tester.line":"En testare kollar varje överlämning först och visar vad den såg.","website.name":"Webbplatsen","website.line":"aigile.lol, teasern och den här tidslinjen.","streaming.name":"Chatt och streaming","streaming.line":"Discord, Twitch, OBS, streamarläge, gif:ar och emojis.","no-ai.name":"Utgåvan utan AI","no-ai.line":"En tavla för folk som kodar utan AI, och publika tavlor.","night-watch.name":"Nattvakt","night-watch.line":"En vakt och Scrum Master håller teamen på spåret medan du sover.","p-more.name":"Allt annat","p-more.line":"Mindre idéer som väntar på sin tur.","p-android.name":"Telefon och Android","p-android.line":"Nå tavlan från telefonen, sedan en egen Android-app.","p-release.name":"Alfa och vidare","p-release.line":"Sluten alfa, den levande sajten, sedan beta.","p-languages.name":"Fler språk","p-languages.line":"Över hundra språk, och ett immersionsläge för den som lär sig.","p-engines.name":"Fler AI-motorer","p-engines.line":"Välj Claude, Codex eller Gemini per agent.","p-pro.name":"Proffsvanor","p-pro.line":"Risketiketter, merge-grindar, incidentkort och skyddsräcken.","p-self.name":"Att ta hand om dig","p-self.line":"Trött-läge, påminnelser om att ta hand om dig själv och 4:20.","p-servers.name":"Servrar och skala","p-servers.line":"Globala serverinställningar, roller och planering för tillväxt.","p-livestream.name":"Streamingextra","p-livestream.line":"Twitch-chatt, egna emojis och en publik livevy."},"words":{"button":"📖 Utvecklarord","h":"📖 Utvecklarord förklarade","intro":"Orden som utvecklare (och AI-teamen) använder, på vanlig svenska.","search":"Sök efter ett ord…","none":"Inget ord matchar.","close":"Stäng","list":[{"id":"backlog","word":"Backlog","text":"Idéer och arbete som inte är planerade än. Inget där påbörjas förrän det flyttas till To do."},{"id":"sprint","word":"Sprint","text":"En kort arbetsperiod (ofta en eller två veckor) med en överenskommen uppsättning kort som ska bli klara.","also":["sprintar","sprints"]},{"id":"standup","word":"Stand-up","text":"En snabb avstämning: vad varje teammedlem gjort, vad de gör härnäst och vad som stoppar dem.","also":["standup","stand-ups"]},{"id":"bug","word":"Bugg","text":"Något som inte fungerar som det ska.","also":["buggar","bug","bugs"]},{"id":"test","word":"Test","text":"Att prova ett färdigt arbete för att kontrollera att det gör det som begärdes, innan du godkänner det.","also":["tester","testa"],"noTip":1},{"id":"commit","word":"Commit","text":"En sparad ögonblicksbild av koden, med en kort anteckning om vad som ändrats. Du kan alltid gå tillbaka till en.","also":["commits"]},{"id":"push","word":"Push","text":"Att skicka sparade ögonblicksbilder (commits) från den här datorn upp till GitHub, så att de är säkerhetskopierade och delade."},{"id":"branch","word":"Branch","text":"En separat arbetslinje i koden, så att ändringar kan göras utan att röra huvudversionen.","also":["branches","gren"]},{"id":"merge","word":"Merge","text":"Att föra in en branchs ändringar i huvudversionen igen."},{"id":"repo","word":"Repo","text":"Projektets mapp med kod och hela historiken av commits, oftast också sparad på GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Att städa i koden utan att ändra vad den gör: mindre filer, tydligare namn, mindre upprepning."},{"id":"deploy","word":"Deploy","text":"Att lansera en ny version, till exempel på en server där folk använder den."},{"id":"kanban","word":"Kanban","text":"En tavla med kolumner (To do, Pågår, Klart) där korten flyttas från vänster till höger medan arbetet pågår."},{"id":"wip","word":"WIP-gräns","text":"Work in progress: det högsta antalet kort en kolumn bör rymma, så att teamet blir klart med saker innan det startar fler.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Att be om att en branchs ändringar ska granskas och föras in i huvudversionen.","also":["PR"]},{"id":"hook","word":"Hook","text":"Ett litet kommando som körs av sig självt vid en viss tidpunkt, t.ex. när en AI-session startar, så att teamet hör dina kommentarer.","also":["hooks"]},{"id":"token","word":"Token","text":"Enheten som AI-användning räknas i: ungefär några få bokstäver text som läses eller skrivs. Färre tokens, mer kvar av ditt abonnemang.","also":["tokens"]},{"id":"agent","word":"Agent","text":"En AI som jobbar självständigt med en uppgift: läser koden, gör ändringar, kör kontroller och rapporterar tillbaka.","also":["agenter","agents"]}]}};
